+// =============================================================================
+// KS-1072 — the latest-anchor selector documents a `confirmedAt` tiebreak it
+// does not implement — and since KS-1057 that selector decides the verdict
+// =============================================================================
+//
+// In `makeFetchDocFromAnchorStore`, inside the anchor-store lookup tier of
+// `POST /api/documents/:id/verify`, two anchors with the same `blockNumber` are
+// ordered arbitrarily because the comparator only looks at `blockNumber`. The
+// comment on line 287 promises *\"Latest = highest blockNumber, fall back to
+// most-recent confirmedAt.\"* but the code never implements the fallback. Since
+// KS-1057 this selection decides the verdict (`verified`, `blockchainAnchored`,
+// `confidence`) for every third-party verifier reaching via tier 2, an arbitrary
+// choice between two equal-height anchors is now a real correctness bug.
+//
+// Driven against the REAL router with a stub server that plays originate AND
+// anchoring over HTTP, copied from ks1071's harness shape so the test reaches
+// `makeFetchDocFromAnchorStore` through its actual call site in the verify
+// handler rather than importing internals directly.
+// =============================================================================
+
+import { describe, it, expect, beforeAll, afterAll, vi } from 'vitest';
+import express from 'express';
+import http from 'node:http';
+import type { Server } from 'node:http';
+import type { AddressInfo } from 'node:net';
+import type { RequestHandler } from 'express';
+
+const DOC_ID = 'doc-ks1072';
+const CONTENT_HASH = 'c'.repeat(64);
+
+let gateway: Server;
+let originate: Server;
+let gatewayPort: number;
+const realFetch = globalThis.fetch;
+
+/** Tier-2 rows served by the stub anchor store (under test's control). */
+let anchorStoreRows: Array<Record<string, unknown>> | null = null;
+/** When true the stub originate 404s, forcing the verify route into tier 2. */
+let tier1Absent = false;
+const jsonHead = { 'Content-Type': 'application/json' };
+
+beforeAll(async () => {
+  originate = http.createServer((req, res) => {
+    if (req.url === `/api/anchors/document/${DOC_ID}`) {
+      if (!anchorStoreRows) { res.writeHead(404, jsonHead); res.end('{}'); return; }
+      res.writeHead(200, jsonHead);
+      res.end(JSON.stringify({ data: { anchors: anchorStoreRows } }));
+      return;
+    }
+    if (req.url === `/api/documents/${DOC_ID}`) {
+      if (tier1Absent) { res.writeHead(404, jsonHead); res.end('{}'); return; }
+      res.writeHead(200, jsonHead);
+      res.end(JSON.stringify({ id: DOC_ID, status: 'anchored', contentHash: CONTENT_HASH, owner: { id: 'org-1' }, blockchain: {} }));
+      return;
+    }
+    res.writeHead(404, jsonHead);
+    res.end('{}');
+  });
+  originate.listen(0, '127.0.0.1');
+  await new Promise<void>((r) => originate.once('listening', () => r()));
+  const originatePort = (originate.address() as AddressInfo).port;
+
+  // Default is a 404 — no live evidence — so every cell measures its persisted blob.
+  globalThis.fetch = (async () => ({ ok: false, status: 404, json: async () => ({}), text: async () => '' })) as never;
+
+  const { createVerificationRoutes } = await import('../routes/verification');
+  const mockBodyParser: RequestHandler = express.json({ limit: '1mb' });
+
+  const app = express();
+  app.use(
+    createVerificationRoutes({
+      authenticateToken: () => (req, _res, next) => {
+        (req as { user?: unknown }).user = {
+          userId: 'u1', email: 'u@secuura.local', role: 'ADMIN',
+          organizationId: 'org-1', tenantId: 't1', verificationLevel: 'FULL',
+        };
+        next();
+      },
+      mockBodyParser,
+      query: vi.fn(async () => ({ rows: [] })) as never,
+      isDbAvailable: () => false,
+      redisService: {
+        getPendingDocument: vi.fn(async () => null),
+        deletePendingDocument: vi.fn(async () => undefined),
+        getAllDocumentTypes: vi.fn(async () => []),
+        getAllWorkflowInstances: vi.fn(async () => []),
+        getNotificationSettings: vi.fn(async () => ({})),
+        getRejectedDocument: vi.fn(async () => null),
+        setRejectedDocument: vi.fn(async () => undefined),
+        getWorkflowDocumentMapping: vi.fn(async () => null),
+        getWorkflowInstance: vi.fn(async () => null),
+        setWorkflowInstance: vi.fn(async () => undefined),
+      } as never,
+      services: { originate: { url: `http://127.0.0.1:${originatePort}` }, anchoring: { url: `http://127.0.0.1:${originatePort}` } } as never,
+      log: () => undefined,
+      memWorkflowToDocumentMap: new Map(),
+      memRejectedDocuments: new Map(),
+      dbSaveRejection: vi.fn(async () => undefined),
+      ADMIN_ROLES: ['ADMIN', 'admin'],
+      enforceDocumentTypeRules: vi.fn(async () => ({ ok: true, docType: {} })) as never,
+      createWorkflowInstanceIfRequired: vi.fn(async () => ({ gated: false })) as never,
+      meetsVerificationLevel: () => true,
+    }),
+  );
+
+  gateway = app.listen(0, '127.0.0.1');
+  await new Promise<void>((r) => gateway.once('listening', () => r()));
+  gatewayPort = (gateway.address() as AddressInfo).port;
+});
+
+afterAll(async () => {
+  globalThis.fetch = realFetch;
+  await new Promise<void>((r) => gateway.close(() => r()));
+  await new Promise<void>((r) => originate.close(() => r()));
+});
+
+async function post(): Promise<any> {
+  const r = await realFetch(`http://127.0.0.1:${gatewayPort}/api/documents/${DOC_ID}/verify`, {
+    method: 'POST',
+    headers: { 'Content-Type': 'application/json', Authorization: 'Bearer t' },
+    body: JSON.stringify({ purpose: 'test' }),
+  });
+  expect(r.status).toBe(200);
+  return r.json();
+}
+
+/** Tier 2: originate 404s; the stub anchor store serves `rows`. */
+async function verifyTier2(rows: Array<Record<string, unknown>>): Promise<any> {
+  tier1Absent = true;
+  anchorStoreRows = rows.map((row) => ({ contentHash: CONTENT_HASH, ...row }));
+  return post();
+}
+
+describe('KS-1072 — latest-anchor confirmedAt tiebreak', () => {
+  it('🔴 KS-1072 — equal blockNumber: the most recent confirmedAt wins', async () => {
+    // Base defect: stable sort keeps the first element when byBlock === 0 and
+    // no tiebreak runs, so OLD FIRST in the array stays selected even though B
+    // has a newer confirmedAt. After fix: B is selected because its confirmedAt
+    // parses later than A's.
+    const body = await verifyTier2([
+      { transactionHash: 'a'.repeat(64), blockNumber: 100, status: 'confirmed', confirmedAt: '2026-01-01T00:00:00Z', id: 'anchor_old' },
+      { transactionHash: 'b'.repeat(64), blockNumber: 100, status: 'confirmed', confirmedAt: '2026-06-01T00:00:00Z', id: 'anchor_new' },
+    ]);
+    expect(body.blockchain.source).toBe('persisted');
+    expect(body.documentId).toBe(DOC_ID);
+    expect(body.verified).toBe(true);
+    expect(body.blockchain.txHash).toBe('b'.repeat(64));
+    expect(body.blockchain.confidence).toBe('on-chain');
+  });
+
+  it('🔴 KS-1072 — a missing confirmedAt loses the tiebreak', async () => {
+    // Base defect: an undefined/missing confirmedAt yields NaN from Date.parse,
+    // which coerces to 0 via || 0 — same as a real date of epoch zero. The dated
+    // second row should win but on untouched code the first (no-date) row can
+    // stay selected depending on sort stability. After fix: the dated one wins
+    // deterministically because `Date.parse(undefined)` → NaN → 0 < any real ISO.
+    const body = await verifyTier2([
+      { transactionHash: 'a'.repeat(64), blockNumber: 50, status: 'confirmed', id: 'anchor_no_date' },
+      { transactionHash: 'b'.repeat(64), blockNumber: 50, status: 'confirmed', confirmedAt: '2026-03-15T12:00:00Z', id: 'anchor_dated' },
+    ]);
+    expect(body.blockchain.source).toBe('persisted');
+    expect(body.verified).toBe(true);
+    expect(body.blockchain.txHash).toBe('b'.repeat(64));
+  });
+
+  it('KS-1072 control — a higher blockNumber still wins regardless of confirmedAt', async () => {
+    // Green at base and after. blockNumber is the primary key; this cell proves
+    // the tiebreak does not regress that ordering. An anchor with blockNumber 101
+    // and an old confirmedAt must beat one with blockNumber 100 and a new date.
+    const body = await verifyTier2([
+      { transactionHash: 'a'.repeat(64), blockNumber: 101, status: 'confirmed', confirmedAt: '2020-01-01T00:00:00Z', id: 'anchor_high_block_old_date' },
+      { transactionHash: 'b'.repeat(64), blockNumber: 100, status: 'confirmed', confirmedAt: '2026-12-01T00:00:00Z', id: 'anchor_low_block_new_date' },
+    ]);
+    expect(body.blockchain.source).toBe('persisted');
+    expect(body.verified).toBe(true);
+    expect(body.blockchain.txHash).toBe('a'.repeat(64));
+    expect(body.blockchain.blockHeight).toBe(101);
+  });
+});
